def validate_isolated_plan(raw, segments, picture_count, req):
    """Validate shoot orders without demanding a 9B-written state ledger."""
    from banana_mv.scene_state import parse_object, digest, SceneStateError
    from banana_mv.mv_scope import validate_ending, ending_contract
    raw = parse_object(raw)
    rows = raw.get('segments')
    if not isinstance(rows,list) or len(rows)!=len(segments):
        raise SceneStateError(f'需要 {len(segments)} 段獨立劇本，實際取得 '
                              f'{len(rows) if isinstance(rows,list) else 0} 段。')
    constraints=raw.get('constraints',[])
    if not isinstance(constraints,list) or any(not isinstance(x,str) for x in constraints):
        raise SceneStateError('constraints 必須是文字清單。')
    ending_plan=validate_ending(raw,req,segments)
    closing=raw.get('closing_shot','')
    if not isinstance(closing,str):
        raise SceneStateError('closing_shot 必須是文字。')
    if req.get('project_scope')!='excerpt' and not closing.strip():
        raise SceneStateError('整首 MV 必須指定最後畫面。')
    allocation=[]
    stable_references={}
    for seg,row in zip(segments,rows):
        if not isinstance(row,dict) or not isinstance(row.get('event'),str) or not row['event'].strip():
            raise SceneStateError(f'第 {seg["index"]+1} 段缺少具體劇本。')
        if row.get('mode') not in MODES:
            raise SceneStateError(f'第 {seg["index"]+1} 段導演模式無效。')
        if 'index' in row and row['index']!=seg['index']:
            raise SceneStateError('導演分段順序錯誤。')
        cast=row.get('cast')
        if not isinstance(cast,list) or len(cast)>32:
            raise SceneStateError(f'第 {seg["index"]+1} 段需有 cast 清單，可為空。')
        chars={}
        ending_looks={}
        visibility={}
        for actor in cast:
            if not isinstance(actor,dict):
                raise SceneStateError('cast 成員必須是角色物件。')
            sid=actor.get('id');ref=actor.get('picture')
            if not isinstance(sid,str) or not re.fullmatch(r'S[1-9]\d*',sid) or sid in chars:
                raise SceneStateError('角色 ID 必須是獨立的 S1、S2 等。')
            if ref is not None and (isinstance(ref,bool) or not isinstance(ref,int)
                                    or not 1<=ref<=picture_count):
                raise SceneStateError('角色圖片編號不存在。')
            if sid in stable_references and stable_references[sid]!=ref:
                raise SceneStateError(f'角色 {sid} 在不同段落引用不同原始圖片。')
            stable_references[sid]=ref
            look=actor.get('appearance','');location=actor.get('location','')
            end_look=actor.get('end_appearance',look)
            end_location=actor.get('end_location',location)
            timing=actor.get('visibility','throughout')
            if (not isinstance(look,str) or not isinstance(location,str)
                    or not isinstance(end_look,str) or not isinstance(end_location,str)):
                raise SceneStateError('角色外觀與位置必須是文字。')
            if timing not in ('opening','closing','throughout','intermittent'):
                raise SceneStateError('角色 visibility 必須是 opening、closing、throughout 或 intermittent。')
            visibility[sid]=timing
            chars[sid]={'original_reference':ref,'hairstyle':'','location':location,
                        'wearing':[],'not_wearing':[],
                        'appearance_changes':[look] if look.strip() else [],
                        'injuries':[],'held_props':[]}
            if end_look!=look or end_location!=location:
                ending_looks[sid]=(end_look,end_location)
        transitions=row.get('transitions',[])
        if not isinstance(transitions,list):
            raise SceneStateError('transitions 必須是清單。')
        normalized=[]
        for transition in transitions:
            if (not isinstance(transition,dict)
                    or transition.get('from') not in chars
                    or transition.get('to') not in chars
                    or transition['from']==transition['to']):
                raise SceneStateError('角色交接的 from/to 必須指向當段兩個不同 cast ID。')
            normalized.append({'from':transition['from'],'to':transition['to']})
            if visibility[transition['from']]=='throughout':
                visibility[transition['from']]='opening'
            if visibility[transition['to']]=='throughout':
                visibility[transition['to']]='closing'
        appearance={'characters':chars,'environments':{}}
        after_chars={sid:dict(actor) for sid,actor in chars.items()}
        for sid,(end_look,location) in ending_looks.items():
            after_chars[sid]['appearance_changes']=[end_look] if end_look.strip() else []
            after_chars[sid]['location']=location
        ending_appearance={'characters':after_chars,'environments':{}}
        allocation.append({'index':seg['index'],'event':row['event'].strip(),
                           'mode':row['mode'],'subjects':list(chars),
                           'cast_visibility':visibility,'transitions':normalized,
                           'source_ids':[],'completed_source_ids':[],
                           'appearance_in':appearance,'appearance_out':ending_appearance})
    plan={'version':3,'initial_state':{},'event_catalog':{},
          'segments':allocation,'constraints':constraints,'closing_shot':closing,
          'requires_change':[],'visual_verified':False,'isolated_shoot_orders':True}
    if 'project_scope' in req:
        plan.update(project_scope=req['project_scope'],ending_plan=ending_plan,
                    ending_contract=ending_contract(req,segments[-1]['start']+segments[-1]['seconds'],segments))
    plan['content_sha256']=digest(plan)
    return plan


def validate_unified_plan(raw,segments,picture_count,req=None):
    from copy import deepcopy
    from banana_mv.scene_state import (parse_object, initial_state, compile_direction_record,
                                       clip_input, digest, OPERATIONS, SceneStateError)
    raw=parse_object(raw)
    rows=raw.get('segments');events=raw.get('events')
    if not isinstance(rows,list) or len(rows)!=len(segments):
        actual=len(rows) if isinstance(rows,list) else None
        message=(f'segments需依順序包含{len(segments)}個區間；實際為'
                 +(str(actual)+'個' if actual is not None else type(rows).__name__)
                 +'。故事事件數不等於影片區間數，請依時間線重新分配，保留收尾。')
        raise SceneStateError(message,[{'path':'$.segments','code':'segment_count_mismatch',
            'expected_count':len(segments),'actual_count':actual,'actual_type':type(rows).__name__,
            'message':message}])
    for i,row in enumerate(rows):
        if isinstance(row,dict) and 'index' in row and (
            isinstance(row['index'],bool) or not isinstance(row['index'],int) or
            row['index']!=segments[i]['index']):
            raise SceneStateError(f'segments[{i}].index需為{segments[i]["index"]}。')
    if not isinstance(events,list) or len(events)>128:raise SceneStateError('events需為最多128項的清單。')
    constraints=raw.get('constraints')
    if not isinstance(constraints,list) or any(not isinstance(t,str) or not t.strip() for t in constraints):
        raise SceneStateError('constraints需為明確角色與限制的文字清單，可為空。')
    from banana_mv.mv_scope import validate_ending
    ending=validate_ending(raw,req or {},segments)
    closing=raw.get('closing_shot')
    excerpt=(req or {}).get('project_scope')=='excerpt'
    if not excerpt and (not isinstance(closing,str) or not closing.strip()):raise SceneStateError('缺少歌曲結束時的最後畫面closing_shot。')
    closing=closing or ''
    def indices(values,path):
        if not isinstance(values,list) or any(isinstance(v,bool) or not isinstance(v,int) or not 0<=v<len(events) for v in values):
            raise SceneStateError(path+'需引用有效事件索引。')
        if len(values)!=len(set(values)):raise SceneStateError(path+'含重複事件。')
        return [f'E{v+1}' for v in values]
    catalog_rows=[]
    for i,e in enumerate(events):
        if not isinstance(e,dict):raise SceneStateError(f'events[{i}]需為物件。')
        ops=e.get('operations',[])
        if not isinstance(ops,list) or any(not isinstance(op,str) or op not in OPERATIONS for op in ops):
            raise SceneStateError(f'events[{i}].operations無效。')
        if not isinstance(e.get('requires_change',False),bool):raise SceneStateError('requires_change需為布林值。')
        catalog_rows.append({'event_id':f'E{i+1}','description':e.get('description'),
            'repeatable':e.get('repeatable',False),'reserved_final':e.get('reserved_final',False),
            'depends_on':indices(e.get('after',[]),f'events[{i}].after'),'allowed_operations':ops})
    initial=deepcopy(raw.get('initial_state'))
    if not isinstance(initial,dict):raise SceneStateError('缺少initial_state。')
    chars=initial.get('character_states',{})
    if isinstance(chars,dict):
        for c in chars.values():
            if not isinstance(c,dict):continue
            garments=c.get('garments',{})
            if isinstance(garments,dict):
                for gid,g in garments.items():
                    if isinstance(g,dict):
                        if 'garment_id' in g and g['garment_id']!=gid:
                            raise SceneStateError('新計畫的衣物key與明確ID矛盾，請修復。')
                        g['garment_id']=gid
    # A technical continuity event satisfies the legacy ledger's nonempty schema;
    # it is never assigned to a clip or imposed on the creative plan.
    state,catalog=initial_state({'initial_state':initial,'events':catalog_rows or [
        {'event_id':'continuity','description':'Unchanged continuity','repeatable':True}]},segments,picture_count)
    allocation=[]
    for i,row in enumerate(rows):
        if not isinstance(row,dict) or not isinstance(row.get('event'),str) or not row['event'].strip():
            raise SceneStateError(f'segments[{i}].event需為具體畫面任務。')
        if row.get('mode') not in MODES:raise SceneStateError(f'segments[{i}].mode無效。')
        refs=indices(row.get('event_indices'),f'segments[{i}].event_indices')
        done=indices(row.get('completed_indices'),f'segments[{i}].completed_indices')
        if set(done)-set(refs):raise SceneStateError('完成事件需屬於當段事件。')
        changes=row.get('changes',[])
        if not isinstance(changes,list):raise SceneStateError('changes需為清單。')
        for change in changes:
            if not isinstance(change,dict):raise SceneStateError('change需為物件。')
            indices([change.get('event_index')],f'segments[{i}].changes.event_index')
        allocation.append(dict(row,index=segments[i]['index'],source_ids=refs,
                               completed_source_ids=done))
    sources=[{'id':c['event_id'],'event':c['description'],'repeatable':c['repeatable']} for c in catalog_rows]
    errors=allocation_errors(sources,allocation)
    if errors:raise SceneStateError('; '.join(errors))
    plan={'version':3,'initial_state':state,'event_catalog':catalog,'segments':allocation,
          'constraints':constraints,'closing_shot':closing.strip(),
          'requires_change':[f'E{i+1}' for i,e in enumerate(events) if e.get('requires_change',False)],
          'visual_verified':False}
    if req and 'project_scope' in req:
        from banana_mv.mv_scope import ending_contract
        plan.update(project_scope=req['project_scope'],ending_plan=ending,
                    ending_contract=ending_contract(req,segments[-1]['start']+segments[-1]['seconds'],segments))
    ledger={'initial_state':state,'event_catalog':catalog,'commits':[]}
    # Execute all deterministic transitions now, before any GPU work. The model
    # cannot validate a plan by deleting metadata and leaving its state unchanged.
    for seg,row in zip(segments,allocation):
        incoming=clip_input(ledger,seg)
        record=compile_direction_record(row,incoming,catalog,seg,plan['requires_change'])
        from banana_mv.prompt_quality import visual_state
        subjects=row.get('subjects')
        if (req or {}).get('prompt_compiler_version')==1 and subjects is None:
            raise SceneStateError(f'segments[{i}].subjects需列出當段入鏡角色，無角色時為[]。')
        if subjects is not None and (not isinstance(subjects,list) or
            any(not isinstance(s,str) or s not in state['character_states'] for s in subjects)):
            raise SceneStateError('subjects需引用已知角色。')
        row['appearance_in']=visual_state(record['scene_state_in'],subjects)
        row['appearance_out']=visual_state(record['scene_state_out'],subjects)
        ledger['commits'].append(record)
    plan['content_sha256']=digest(plan)
    return plan


DIRECT_PROMPT_SYSTEM = """Deliver the final filming prompts for ONE chronological music video.
The brief is the whole story; each timeline row is one fixed source interval.
Write only that interval's events. Never replay earlier events or pull future
chapters into the opening. Carry current identity, clothing and props, not history.
Honor local_srt and explicit cue-bound actions. FREE staging preserves causal order.
Use each actor's ORIGINAL <Picture N> binding, offset by picture_offset; with
an offset of 1, Picture 1 is the previous last frame, not an additional actor.
Only actors with a part in this interval appear. Use compatible music-video cuts
and motion; any shot times are LOCAL, within seconds. Only the assigned singer
lip-syncs; <Audio 1>: fully_copy. No new speech, lyrics or subtitles.
Follow each row's ending: excerpts stay open, full works resolve and hold in time.
No downstream writer will reinterpret these prompts. Write concise, self-contained
filming prose directly, not analysis, instructions for another writer, or JSON.
Use these boundary lines (zero-based index and one supported mode):
=== CLIP 0 action ===
The complete final filming prompt for interval 0, with original picture bindings.
=== CLIP 1 story ===
The complete final filming prompt for interval 1 only.
=== END ===
Return every requested clip, then the END line. Nothing before or after the blocks.
No separate event synopsis, state ledger or repeated six-section boilerplate."""


def direct_delivery(raw):
    """Read explicit clip boundaries without parsing or rewriting the filming prose."""
    from banana_mv.scene_state import parse_object, SceneStateError
    if not isinstance(raw,str):return parse_object(raw)
    source=re.sub(r'<think>.*?</think>','',raw,flags=re.S).strip()
    markers=list(re.finditer(r'^===\s*CLIP\s+(\d+)\s+([a-z]+)\s*===[ \t]*\r?$',source,re.M|re.I))
    if not markers:
        if source.startswith(('{','```json','```\n{')):return parse_object(source)
        raise SceneStateError('導演未交出分段拍攝稿：需有 === CLIP 0 action === 等段落標記。回傳不是空白，但不能把整首稿或分析當成第一段。')
    end=re.search(r'^===\s*END\s*===[ \t]*\r?$',source,re.M|re.I)
    if not end or end.start()<markers[-1].end():
        raise SceneStateError('導演交稿缺少 === END ===，可能尚未完成或回傳已截斷；不會送出半份拍攝稿。')
    if source[end.end():].strip() not in ('','```'):
        raise SceneStateError('導演結束標記後仍有內容，無法確定段落範圍。')
    rows=[]
    for i,marker in enumerate(markers):
        stop=markers[i+1].start() if i+1<len(markers) else end.start()
        rows.append({'index':int(marker[1]),'mode':marker[2].lower(),
                     'prompt':source[marker.end():stop].strip()})
    return {'segments':rows,'direct_blocks':True}


def validate_direct_prompts(raw,segments,picture_count,req):
    """Check delivery completeness and connected media, never direct the shots again."""
    from banana_mv.scene_state import parse_object, digest, SceneStateError
    from banana_mv.core import normalize_mv_prompt
    from banana_mv.mv_scope import validate_ending, ending_contract
    raw=direct_delivery(raw);rows=raw.get('segments')
    if not isinstance(rows,list) or len(rows)!=len(segments):
        raise SceneStateError(f'導演需交齊 {len(segments)} 段最終提示詞。')
    result=[]
    for seg,row in zip(segments,rows):
        if not isinstance(row,dict) or row.get('index')!=seg['index']:
            raise SceneStateError('導演分段順序錯誤。')
        if row.get('mode') not in MODES:
            raise SceneStateError('導演模式無效。')
        prompt=row.get('prompt')
        if not isinstance(prompt,str) or not prompt.strip():
            raise SceneStateError(f'第 {seg["index"]+1} 段缺少最終提示詞。')
        offset=int(req.get('mode')=='chain' and seg['index']>0)
        prompt=normalize_mv_prompt(prompt,picture_count+offset)
        if picture_count>1 and not re.search(r'<Picture \d+>',prompt):
            raise SceneStateError(f'第 {seg["index"]+1} 段未綁定任何原始參考圖；多圖提示詞需明確使用 <Picture N>。')
        event=row.get('event','')
        result.append({'index':seg['index'],'event':event if isinstance(event,str) else '',
                       'mode':row['mode'],'prompt':prompt})
    closing=raw.get('closing_shot','')
    if not isinstance(closing,str):raise SceneStateError('closing_shot 必須是文字。')
    plan={'version':4,'segments':result,'constraints':[],'requires_change':[],
          'closing_shot':closing,'ending_plan':None if raw.get('direct_blocks') else validate_ending(raw,req,segments),
          'project_scope':req.get('project_scope','full'),
          'ending_contract':ending_contract(req,segments[-1]['start']+segments[-1]['seconds'],segments),
          'visual_verified':False,'direct_prompts':True}
    plan['content_sha256']=digest(plan)
    return plan


def ensure_unified_plan(cfg,req,segments,originals,work,rewrite):
    from banana_mv.scene_state import (digest, atomic_json, rewrite_retry_count, SceneStateError,
                                       parse_object as parse_scene_object_for_diagnostics)
    direct=req.get('director_schema')==4
    task={'brief':req.get('prompt',''),'adaptation':'FREE' if req.get('story_plan',True) else 'FAITHFUL',
          'style':req.get('director','auto'),'intensity':req.get('intensity','high'),
          'lyrics':req.get('lyrics',''),'srt':req.get('srt_cues',[]),
          'timeline':[{k:s[k] for k in ('index','start','seconds')} |
                      {'audio_evidence':s.get('audio_evidence',{})} for s in segments]}
    if req.get('prompt_compiler_version')==1:
        task['prompt_compiler_version']=1
    if direct:
        from banana_mv.core import map_image_mentions
        task['brief']=map_image_mentions(task['brief'],len(originals))
        task['direct_prompts']=True
        task['delivery_format']='clip_blocks_v1'
        for row in task['timeline']:
            row['picture_offset']=int(req.get('mode')=='chain' and row['index']>0)
            start=row['start'];end=start+row['seconds']
            row['source_end']=end
            from banana_mv.mv_scope import clip_ending
            row['ending']=clip_ending(req,dict(row,song_seconds=segments[-1]['start']+segments[-1]['seconds'],segment_count=len(segments)))
            row['local_srt']=[{'start':max(0,c['start']-start),
                              'end':min(row['seconds'],c['end']-start),'text':c['text']}
                             for c in req.get('srt_cues',[]) if c['start']<end and c['end']>start]
        task.pop('srt') # Cues are supplied once, in their actual source intervals.
    if 'project_scope' in req:
        from banana_mv.mv_scope import ending_contract
        task['ending_contract']=ending_contract(req,segments[-1]['start']+segments[-1]['seconds'],segments)
    # Slot scaffolding is an output contract, not creative input: keep the saved
    # plan fingerprint compatible with already successful version-3 projects.
    fingerprint=digest(task);path=Path(work)/'director_plan.json'
    if path.is_file():
        plan=json.loads(path.read_text(encoding='utf-8'))
        expected=plan.get('content_sha256')
        if plan.get('version')!=(4 if direct else 3) or plan.get('input_sha256')!=fingerprint or digest(
            {k:v for k,v in plan.items() if k not in ('input_sha256','content_sha256')})!=expected:
            raise SceneStateError('統一導演計畫與專案不符或校驗失敗。')
        if plan.get('isolated_shoot_orders') and 'project_scope' in req:
            from banana_mv.mv_scope import validate_ending
            try:
                validate_ending(plan,req,segments)
            except ValueError as error:
                raise SceneStateError('已存導演計畫的結尾資料無效，請建立新任務重新規劃：'+str(error)) from error
        return plan
    isolated=req.get('scene_state_version',1)==0
    task['required_segment_count']=len(segments)
    if direct:
        task['prompt_word_budget']=max(40,min(160,(int(cfg.get('rewriter',{}).get('max_length',8192))-1000)//(2*len(segments))))
    elif isolated:
        task['segment_template']=[{'index':s['index'],'event':'','mode':'performance',
                                   'cast':[]} for s in segments]
    else:
        task['segment_template']=[{'index':s['index'],'event':'','mode':'performance',
            'event_indices':[],'completed_indices':[],'changes':[]} for s in segments]
        if req.get('prompt_compiler_version')==1:
            for row in task['segment_template']:row['subjects']=[]
    from PIL import Image, ImageOps
    parts=[('text',json.dumps(task,ensure_ascii=False))]
    for i,p in enumerate(originals,1):
        with Image.open(p) as im:
            im=ImageOps.exif_transpose(im).convert('RGB');im.thumbnail((768,768))
            parts.extend([('text',f'<Picture {i}> (original reference {i}):' if direct else f'Original reference {i}:'),('image',im.copy())])
    system=(DIRECT_PROMPT_SYSTEM if direct else ISOLATED_SYSTEM if isolated else UNIFIED_SYSTEM)+'\nSupported primary modes: '+', '.join(MODES)+f'\nEXACTLY {len(segments)} segments.'
    if direct:
        from banana_mv.director import ORIGINAL_CUT_GUIDANCE, INTENSITY
        system+='\n'+(ORIGINAL_CUT_GUIDANCE if req.get('dynamic_cuts',True) else 'Prefer motivated longer takes.')
        system+='\n'+INTENSITY[req.get('intensity','high')]
        system+='\nWhen the assigned singer is visible, use waist-up or closer. '+('Preserve reference facial identity. ' if req.get('face_identity',True) else '')
        system+='\nKeep each prompt within prompt_word_budget words.'
    if req.get('prompt_compiler_version')==1 and not isolated:
        system+=('\nEach segment also needs subjects: a list of visible character IDs from initial_state, '
                 'including non-singing story actors; [] for a character-free scene. Include both casts '
                 'for a full-frame intercut, never merge separate locations. Lyrics and SRT offer optional '
                 'theme and timing, subordinate to the supplied visual story; do not illustrate each line '
                 'or invent conflicting people, objects or events. A location or reference image is not a story action.')
    if 'project_scope' in req and not direct:
        system+=('\nENDING SCOPE OVERRIDES generic closing instructions: obey ending_contract. '
                 'For excerpt return ending_plan=null and closing_shot=""; no full-work resolution. '
                 'For full return ending_plan={"start_time":absolute source seconds, '
                 '"resolved_by":absolute source seconds,"resolution":"how the supplied main arc concludes"}. '
                 'Allocate that resolution across the actual affected segment rows, finish it by settle_by, '
                 'then hold closing_shot through the source end. No new action in a tiny final tail. '
                 'Write the visible completion action, its established result, and arrival at the final '
                 'pose/framing/light into the affected segment events; a camera cut alone is not resolution.')
    attempt_parts=parts;seen=set()
    for attempt in range(rewrite_retry_count(req)+1):
        raw=rewrite(cfg,system,attempt_parts,uuid.uuid4().hex[:8])
        try:
            plan=(validate_direct_prompts(raw,segments,len(originals),req) if direct else validate_isolated_plan(raw,segments,len(originals),req) if isolated
                  else validate_unified_plan(raw,segments,len(originals),req))

        except ValueError as error:
            signature=digest({'raw':raw,'error':str(error)})
            try:
                parsed=direct_delivery(raw) if direct else parse_scene_object_for_diagnostics(raw)
            except ValueError:
                parsed=None
            atomic_json(Path(work)/f'director_attempt_{attempt:02d}.json',
                        {'raw_response':raw,'parsed_response':parsed,'error':str(error),
                         'errors':getattr(error,'errors',[]),
                         'expected_segment_count':len(segments),
                         'actual_segment_count':len(parsed['segments']) if isinstance(parsed,dict)
                             and isinstance(parsed.get('segments'),list) else None})
            if signature in seen or attempt>=rewrite_retry_count(req):
                raise SceneStateError('統一導演計畫修復失敗：'+str(error)) from error
            seen.add(signature)
            if direct:
                attempt_parts=parts+[('text',f'Deliver ALL {len(segments)} final clip blocks, then === END ===. '
                    'No analysis or JSON. Keep each block within prompt_word_budget; preserve its source interval and picture bindings. '
                    'Delivery error: '+str(error))]
            else:
                attempt_parts=parts+[('text','Repair only invalid structure/continuity in this treatment; '
                    'preserve valid creative choices. Do not map one story milestone to one video interval. '
                    +f'Return ALL {len(segments)} segment_template rows, including the final short interval; '
                    +'distribute actions over the full timeline and preserve closing_shot. '
                    +'Do not pad with replayed completed actions or dummy state updates. Error: '
                    +str(error)+'\nFailed response (data):\n'+str(raw))]
            continue
        plan['input_sha256']=fingerprint
        atomic_json(path,plan)
        return plan


def plan_context(segment, creative=False):
    row = segment.get('director_plan')
    if not row:
        return ''
    if creative:
        text=('DIRECTOR TREATMENT — CURRENT CLIP: '+row['event']
              +'\nUse this musical beat as your creative starting point; restage action, framing and cut order '
              'as needed within this clip. Preserve reference roles and explicit hard restrictions. '
              'The complete user outline is material, not a mandatory shot sequence.')
    else:
        text = ('CURRENT SEGMENT EVENT ALLOCATION (the user brief still governs roles and exclusions): '
            + row['event'] + '\nDevelop ONLY this allocated event, with a readable action and consequence. '
            'Other whole-song events are reserved for their own intervals; do not restart the opening or jump to the finale.')
    previous = segment.get('previous_planned_event')
    if previous:
        text += '\nPrevious planned event (not visually verified): ' + previous + '\nAdvance from its intended outcome; do not replay it.'
    return text


